html:
{% set pf_currency = doc.currency or frappe.db.get_value("Company", doc.company, "default_currency") or frappe.db.get_single_value("Global Defaults", "default_currency") or "" %}
<style>
@page { size: A4; margin: 10mm 12mm 12mm 12mm; }
*, body, .print-format { box-sizing: border-box; font-family: Arial, Helvetica, sans-serif; font-size: 10px; color: #333; line-height: 1.35; }
.promo-container { width: 100%; min-height: 270mm; position: relative; }
.title-row { display: flex; align-items: center; margin: 8px 0 18px; }
.title-line { flex: 1; height: 1px; background: #c5c5c5; }
.promo-title { padding: 0 16px; margin: 0; font-size: 20px; font-weight: 500; color: #222; white-space: nowrap; }
.information-table { width: 100%; border-collapse: collapse; margin-bottom: 18px; }
.information-table td { border: none !important; vertical-align: top; padding: 0; }
.left-section { width: 55%; padding-top: 18px !important; }
.right-section { width: 45%; }
.section-label { color: #777; font-size: 11px; margin-bottom: 2px; }
.main-name { font-size: 13px; font-weight: bold; color: #333; margin-bottom: 4px; }
.details-table { width: 100%; border-collapse: collapse; font-size: 10px; }
.details-table td { border: 1px solid #222 !important; padding: 5px 10px; height: 26px; }
.details-table .detail-label { width: 38%; background: #909090; color: white; }
.details-table .detail-value { width: 62%; color: #222; font-weight: 500; }
.item-table { width: 100%; border-collapse: collapse; table-layout: fixed; margin-bottom: 20px; border: 1px solid #111; }
.item-table th { background: #929292; color: white; border: 1px solid #111; padding: 7px 6px; font-weight: normal; font-size: 10px; text-align: center; }
.item-table td { padding: 8px 6px; vertical-align: top; border-left: 1px solid #ddd; border-right: 1px solid #ddd; border-top: none; border-bottom: none; font-size: 9.5px; }
.item-table tbody tr:last-child td { padding-bottom: 12px; }
.center { text-align: center; } .right { text-align: right; } .bold { font-weight: 600; color: #222; }
.item-name { font-weight: 500; color: #222; margin-bottom: 2px; }
.item-description { color: #555; line-height: 1.4; word-break: break-word; }
.section-heading { margin: 12px 0 8px; font-size: 12px; font-weight: 600; color: #222; }
.notes-box { border: 1px solid #222; min-height: 42px; padding: 8px 10px; margin-top: 8px; }
.signature-table { width: 100%; border-collapse: collapse; margin-top: 22px; }
.signature-table td { border: none !important; padding: 22px 16px 0 0; width: 25%; }
.signature-line { border-top: 1px solid #222; padding-top: 5px; font-size: 10px; color: #333; }
</style>
<div class="promo-container">
<div class="title-row"><div class="title-line"></div><h1 class="promo-title">Buy X Get Y Promotion</h1><div class="title-line"></div></div>
<table class="information-table"><tr><td class="left-section"><div class="section-label">Promotion</div><div class="main-name">{{ doc.description }}</div><div>Status: <span class="bold">{{ "Disabled" if doc.disabled else "Active" }}</span></div><div>Printed: {{ frappe.utils.format_datetime(frappe.utils.now_datetime(), "dd-MM-yyyy HH:mm") }}</div></td><td class="right-section"><table class="details-table"><tr><td class="detail-label">Active From</td><td class="detail-value">{{ frappe.utils.formatdate(doc.active_from, "dd-MM-yyyy") if doc.active_from else "" }}</td></tr><tr><td class="detail-label">Active To</td><td class="detail-value">{{ frappe.utils.formatdate(doc.active_to, "dd-MM-yyyy") if doc.active_to else "" }}</td></tr><tr><td class="detail-label">Company</td><td class="detail-value">{{ doc.company or "All" }}</td></tr><tr><td class="detail-label">Warehouse</td><td class="detail-value">{{ doc.warehouse or "All" }}</td></tr><tr><td class="detail-label">Buy Qty</td><td class="detail-value">{{ doc.buy_qty }}</td></tr><tr><td class="detail-label">Free Qty</td><td class="detail-value">{{ doc.free_qty }}</td></tr><tr><td class="detail-label">Same Product Only</td><td class="detail-value">{{ "Yes" if doc.same_product_only else "No" }}</td></tr><tr><td class="detail-label">Priority</td><td class="detail-value">{{ doc.priority or "" }}</td></tr></table></td></tr></table>
<div class="section-heading">Promotion Items</div>
<table class="item-table"><thead><tr><th style="width:6%">Sr</th><th style="width:16%">Type</th><th style="width:36%">Item / Group</th><th style="width:10%">UOM</th><th style="width:16%">Shelf / Bay</th><th style="width:16%">Checked</th></tr></thead><tbody>{% for row in doc.products %}<tr><td class="center">{{ loop.index }}</td><td class="bold">{{ row.add_to }}</td><td><div class="item-name">{{ row.item or row.item_group }}</div>{% if row.item and frappe.db.exists("Item", row.item) %}<div class="item-description">{{ frappe.db.get_value("Item", row.item, "item_name") or "" }}</div>{% endif %}</td><td class="center">{{ row.uom or "" }}</td><td></td><td></td></tr>{% endfor %}</tbody></table>
<div class="section-heading">Notes</div><div class="notes-box">{{ doc.notes or "" }}</div>
<table class="signature-table"><tr><td><div class="signature-line">Prepared By</div></td><td><div class="signature-line">Store In-Charge</div></td><td><div class="signature-line">Updated By</div></td><td><div class="signature-line">Verified By</div></td></tr></table>
</div>
